  const qualityPriority = (row) => {
    if (/^(w|pack-)/.test(String(row.id || "")) && row.meaningLanguage !== "en") return 4;
    if (row.meaningLanguage === "vi") return 3;
    if (String(row.id || "").startsWith("jmdict-")) return 2;
    return 1;
  };
