  const defaults = () => ({version:VERSION,activeTab:"today",path:"jf",practiceTool:"lesson",lookupTool:"dictionary",progressTool:"dual",jlptLevel:"N5",jfLevel:"A1",goal:"life",dailyMinutes:15,xp:0,streak:0,lastStudy:"",knownWords:{},vocabMastery:{},cards:[],mistakes:[],missionProgress:{},conversationHistory:[],writingHistory:[],savedSentences:[],sentenceProgress:{},offlinePacks:{},packHistory:[],reviewQueue:[],reviewOverrides:{},particleStats:{},classrooms:[],family:{enabled:false,dailyLimit:20,aiAllowed:false,publicRanking:false},furigana:true,immersionId:"bank",lesson:{wordIds:[],index:0,step:0,answers:{}},activeStats:{recognition:0,recall:0,production:0},activityLog:[]});
  function readState(){try{const raw=JSON.parse(localStorage.getItem(stateKey())||"null");if(raw)return {...defaults(),...raw,cards:Array.isArray(raw.cards)?raw.cards:[],mistakes:Array.isArray(raw.mistakes)?raw.mistakes:[]};const v4=JSON.parse(localStorage.getItem(`hh.japanese.os.v4:${ownerId()}:${learnerId()}`)||"null");if(v4)return {...defaults(),...v4,version:VERSION,practiceTool:"lesson",vocabMastery:v4.vocabMastery||{},reviewQueue:v4.reviewQueue||[],reviewOverrides:v4.reviewOverrides||{}};const old=JSON.parse(localStorage.getItem(`hh.japanese.os.v3:${ownerId()}`)||"null");const state=defaults();if(old){state.xp=Number(old.xp)||0;state.streak=Number(old.streak)||0;state.jlptLevel=old.jlptLevel||"N5";state.jfLevel=old.jfLevel||"A1";state.knownWords=old.knownWords||{};state.missionProgress=old.missionProgress||{};for(const id of Object.keys(old.savedWords||{}))state.cards.push(makeCard("word",id));}return state;}catch{return defaults();}}
  function write(){if(instance)localStorage.setItem(stateKey(),JSON.stringify({...instance.state,version:VERSION,cards:instance.state.cards.slice(-5000),mistakes:instance.state.mistakes.slice(-500),conversationHistory:instance.state.conversationHistory.slice(-200),writingHistory:instance.state.writingHistory.slice(-200),savedSentences:instance.state.savedSentences.slice(-500),reviewQueue:instance.state.reviewQueue.slice(-1000),packHistory:instance.state.packHistory.slice(-100),activityLog:(Array.isArray(instance.state.activityLog)?instance.state.activityLog:[]).slice(-240)}));}
  function recordActivity(type,ref="",detail=""){if(!instance)return;const rows=Array.isArray(instance.state.activityLog)?instance.state.activityLog:[];rows.push({id:`${type}:${Date.now()}:${checksum(ref)}`,type:String(type||"study").slice(0,32),ref:String(ref||"").slice(0,120),detail:String(detail||"").slice(0,180),day:day(),at:new Date().toISOString()});instance.state.activityLog=rows.slice(-240);}
  function study(xp=5){const s=instance.state,t=day();if(s.lastStudy!==t){const yesterday=day(Date.now()-86400000);s.streak=s.lastStudy===yesterday?s.streak+1:1;s.lastStudy=t;}s.xp+=xp;}
  const checksum = (value) => {let hash=2166136261;for(const char of String(value)){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619);}return(hash>>>0).toString(16).padStart(8,"0");};
  function makeCard(type,ref,payload={}){return {id:`${type}:${ref}`,type,ref,payload,status:"new",dueAt:new Date().toISOString(),interval:0,ease:2.5,lapses:0,createdAt:new Date().toISOString()};}
  function addCard(type,ref,payload={}){const id=`${type}:${ref}`,found=instance.state.cards.find((card)=>card.id===id);if(found)return found;const card=makeCard(type,ref,payload);instance.state.cards.push(card);write();return card;}
  function cardStatus(card){const due=Date.parse(card.dueAt||0)<=Date.now();if(card.lapses>1&&due)return"relearning";if(card.status==="mastered"&&!due)return"mastered";if(due&&card.interval>0)return"due";return card.status||"new";}
  function rateCard(card,rating){const now=Date.now(),dayMs=86400000;card.reviews=(card.reviews||0)+1;card.lastReviewedAt=new Date(now).toISOString();if(rating==="forget"){card.status="relearning";card.lapses=(card.lapses||0)+1;card.interval=0;card.dueAt=new Date(now+10*60000).toISOString();card.ease=Math.max(1.3,(card.ease||2.5)-.2);}if(rating==="hard"){card.status="hard";card.interval=Math.max(1,Math.round((card.interval||1)*1.2));card.dueAt=new Date(now+card.interval*dayMs).toISOString();}if(rating==="remember"){card.status="learning";card.interval=Math.max(3,Math.round((card.interval||1)*(card.ease||2.5)));card.dueAt=new Date(now+card.interval*dayMs).toISOString();}if(rating==="easy"){card.status="mastered";card.interval=Math.max(7,Math.round((card.interval||2)*(card.ease||2.5)*1.3));card.dueAt=new Date(now+card.interval*dayMs).toISOString();card.ease=Math.min(3.2,(card.ease||2.5)+.1);}recordActivity("review",card.id,rating);write();}
  function addMistake(category,prompt,correct,actual,ref=""){const key=`${category}:${ref||prompt}`,found=instance.state.mistakes.find((row)=>row.key===key);if(found){found.count+=1;found.actual=actual;found.updatedAt=new Date().toISOString();found.resolved=false;delete found.resolvedAt;}else instance.state.mistakes.push({key,category,prompt,correct,actual,count:1,updatedAt:new Date().toISOString(),resolved:false});addCard(category,ref||checksum(prompt),{prompt,correct});write();}
  function speak(text,rate=1){if(!global.speechSynthesis||!global.SpeechSynthesisUtterance)return false;global.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(String(text||""));utterance.lang="ja-JP";utterance.rate=rate;global.speechSynthesis.speak(utterance);return true;}
  function normalizeJapanese(value){return String(value||"").normalize("NFKC").replace(/[\s。、！？!?.,・「」『』（）()]/g,"");}
  function transcriptScore(expected,actual){if(legacy.scoreDictation)return legacy.scoreDictation(expected,actual);const a=normalizeJapanese(expected),b=normalizeJapanese(actual);if(!a||!b)return 0;let hits=0;for(const char of b)if(a.includes(char))hits++;return Math.min(100,Math.round(hits/Math.max(a.length,b.length)*100));}
  function toast(message,tone="success"){const node=instance?.host.querySelector("[data-hhj4-toast]");if(!node)return;node.textContent=message;node.dataset.tone=tone;node.hidden=false;clearTimeout(instance.toastTimer);instance.toastTimer=setTimeout(()=>node.hidden=true,3600);}
  function metric(label,value,detail){return `<article class="hhj4-metric"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(detail)}</small></article>`;}
  function statusOf(row){if (/^(w|pack-)/.test(String(row.id||""))&&row.meaningLanguage!=="en")return["Đã kiểm duyệt","reviewed"];if(row.reviewStatus==="source-derived"&&row.meaningLanguage==="vi")return["Đã kiểm tra nguồn · cần biên tập","checked"];return["Tự động từ nguồn mở · nghĩa Anh tham chiếu","automatic"];}
  const dueCards = () => instance.state.cards.filter((card)=>cardStatus(card)==="new"||Date.parse(card.dueAt||0)<=Date.now());
  let reviewedVietnameseCache=null;
  const reviewedVietnamese = () => reviewedVietnameseCache||(reviewedVietnameseCache=Object.freeze(ALL_WORDS.filter((row)=>row.meaningLanguage==="vi"||(/^(w|pack-)/.test(String(row.id||""))&&row.meaningLanguage!=="en")).sort((a,b)=>{const aCore=/^w\d+$/.test(String(a.id||"")),bCore=/^w\d+$/.test(String(b.id||""));if(aCore!==bCore)return aCore?-1:1;const aNumber=Number(String(a.id||"").match(/\d+/)?.[0]||999999),bNumber=Number(String(b.id||"").match(/\d+/)?.[0]||999999);return aNumber-bNumber;})));
  let learningVocabularyCache=null;
  function learningVocabulary(){if(learningVocabularyCache)return learningVocabularyCache;const levelRank={N5:0,N4:1,N3:2,N2:3,N1:4,"N?":9};learningVocabularyCache=reviewedVietnamese().slice().sort((a,b)=>{const aCore=/^w\d+$/.test(String(a.id||"")),bCore=/^w\d+$/.test(String(b.id||""));if(aCore!==bCore)return aCore?-1:1;const level=(levelRank[a.level]??8)-(levelRank[b.level]??8);if(level)return level;const aNumber=Number(String(a.id||"").match(/\d+/)?.[0]||999999),bNumber=Number(String(b.id||"").match(/\d+/)?.[0]||999999);return aNumber-bNumber||String(a.word||"").localeCompare(String(b.word||""),"ja");});return learningVocabularyCache;}
  function packCatalog(){const viCount=reviewedVietnamese().length;return [{id:"vi-core",label:"Vietnamese Core",target:8000,count:viCount,status:"mixed",downloadable:true},{id:"sentences-v5",label:"Sentence Bank",target:30000,count:SENTENCES.length,status:"source-filtered",downloadable:true},{id:"kanjivg-v5",label:"KanjiVG Stroke",target:2136,count:strokePack.count,status:"licensed",downloadable:true},...sourcePack.packs];}
  function careerCatalog(){const counts={};for(const row of sourcePack.words)for(const domain of row.domains||[])if(CAREER_LABELS[domain])counts[domain]=(counts[domain]||0)+1;return Object.entries(CAREER_LABELS).map(([id,label])=>({id,label,count:counts[id]||0})).filter((row)=>row.count);}
  function effectiveWord(row){if(!row)return row;const patch=instance?.state.reviewOverrides?.[row.id];return patch?{...row,...patch,reviewStatus:"reviewed-local",meaningLanguage:"vi"}:row;}
  function examplesForWord(word,limit=10){const key=`${word}:${limit}`;if(sentenceCache.has(key))return sentenceCache.get(key);const rows=SENTENCES.filter((row)=>row.text.includes(word)).slice(0,limit);sentenceCache.set(key,rows);return rows;}
  function particleNear(sentence,word){const at=sentence.indexOf(word);if(at<0)return"";const tail=sentence.slice(at+word.length,at+word.length+3);return tail.match(/^(には|では|へは|に|で|へ|は|が|を|と|も)/u)?.[0]||"";}
  function masteryOf(id){return instance.state.vocabMastery[id]||{recognition:0,recall:0,production:0,particle:0,reviews:0};}
  function updateMastery(id,skill,correct){const current={...masteryOf(id)};current[skill]=Math.max(0,Math.min(5,(current[skill]||0)+(correct?1:-1)));current.reviews=(current.reviews||0)+1;current.lastAt=new Date().toISOString();current.mastered=current.recognition>=3&&current.recall>=3&&current.production>=3&&current.reviews>=8;instance.state.vocabMastery[id]=current;if(current.mastered)instance.state.knownWords[id]=true;write();return current;}
  function ensureLesson(){let lesson=instance.state.lesson||(instance.state.lesson={wordIds:[],index:0,step:0,answers:{},curationVersion:1});if(!lesson.wordIds?.length||lesson.curationVersion!==1||lesson.wordIds.some((id)=>!WORD_BY_ID.has(id))){lesson={wordIds:learningVocabulary().filter((row)=>!masteryOf(row.id).mastered).slice(0,12).map((row)=>row.id),index:0,step:0,answers:{},curationVersion:1};instance.state.lesson=lesson;write();}return lesson;}
  function unknownSentenceWords(sentence){const tokens=tokenize(sentence.text).filter((token)=>token.row);const unique=[...new Map(tokens.map((token)=>[token.row.id,token.row])).values()];return unique.filter((row)=>!instance.state.knownWords[row.id]);}
  function nPlusOneSentences(limit=80){const scored=[];for(const row of SENTENCES){const unknown=unknownSentenceWords(row);if(unknown.length<=1)scored.push({row,unknown:unknown.length,coverage:Math.round((1-unknown.length/Math.max(1,tokenize(row.text).filter(x=>x.row).length))*100)});if(scored.length>=limit)break;}return scored;}
  function sentenceStatus(row){const saved=instance.state.sentenceProgress[String(row.id)]||{};return {...saved,reviewStatus:row.reviewStatus,attribution:`${row.author} · ${row.license}`};}

  const POS_GROUPS=Object.freeze([
    ["noun","Danh từ"],["verb","Động từ"],["adjective","Tính từ"],["adverb","Phó từ"],["phrase","Cụm & thành ngữ"],["particle","Trợ từ"],["other","Khác"]
  ]);
  // LESSON PLAYER V5 · sequential steps, active recall and checkpoint restore.
  function posGroup(row){const value=String(row?.pos||"").toLocaleLowerCase("vi");if(/động từ|verb|godan|ichidan|suru/.test(value))return"verb";if(/tính từ|adjectiv|keiyou/.test(value))return"adjective";if(/phó từ|adverb|fukushi/.test(value))return"adverb";if(/cụm|thành ngữ|tục ngữ|expression|phrase|proverb|idiom/.test(value))return"phrase";if(/trợ từ|particle/.test(value))return"particle";if(/danh từ|noun|pronoun|đại từ|tên|địa danh/.test(value))return"noun";return"other";}
  let vocabularyFacetCache=null;
  function vocabularyFacets(){if(vocabularyFacetCache)return vocabularyFacetCache;const topics=new Map(),levels=new Map(),parts=new Map();for(const row of ALL_WORDS){if(row.topic)topics.set(row.topic,(topics.get(row.topic)||0)+1);levels.set(row.level||"N?",(levels.get(row.level||"N?")||0)+1);const group=posGroup(row);parts.set(group,(parts.get(group)||0)+1);}vocabularyFacetCache=Object.freeze({topics:[...topics].sort((a,b)=>b[1]-a[1]).slice(0,18),levels:["N5","N4","N3","N2","N1","N?"].map((id)=>[id,levels.get(id)||0]),parts:POS_GROUPS.map(([id,label])=>[id,label,parts.get(id)||0])});return vocabularyFacetCache;}
  function dictionaryFacetMatch(row){const level=instance.levelFilter||"all",topic=instance.topicFilter||"all",part=instance.posFilter||"all";if(level!=="all"&&String(row.level||"N?")!==level)return false;if(topic!=="all"&&String(row.topic||"")!==topic)return false;if(part!=="all"&&posGroup(row)!==part)return false;return true;}
  function usefulVocabulary(limit=6){const s=instance.state,topicMap={life:["Đời sống","Ẩm thực","Du lịch","Sức khỏe","Chào hỏi","life"],career:["Công việc","Công nghệ","Học thuật","career","business","keigo"],jlpt:["Học tập","Động từ","general"],jf:["Chào hỏi","Đời sống","Du lịch","Công việc"]},wanted=topicMap[s.goal]||topicMap[s.path]||topicMap.life;let rows=learningVocabulary().filter((row)=>String(row.level||"")===String(s.jlptLevel||"N5")&&wanted.includes(row.topic)&&["noun","verb","phrase","adjective"].includes(posGroup(row)));if(rows.length<limit)rows=learningVocabulary().filter((row)=>String(row.level||"")===String(s.jlptLevel||"N5")&&["noun","verb","phrase","adjective"].includes(posGroup(row)));if(rows.length<limit)rows=learningVocabulary().filter((row)=>["noun","verb","phrase","adjective"].includes(posGroup(row)));const offset=parseInt(checksum(`${day()}:${s.goal}:${s.jlptLevel}`).slice(0,6),16)%Math.max(1,rows.length);return [...rows.slice(offset),...rows.slice(0,offset)].slice(0,limit).map(effectiveWord);}
  function dailySnapshot(){const s=instance.state,today=day(),isToday=(value)=>{const timestamp=Date.parse(value);return Number.isFinite(timestamp)&&day(timestamp)===today;},activities=(Array.isArray(s.activityLog)?s.activityLog:[]).filter((row)=>row.day===today),reviews=s.cards.filter((card)=>isToday(card.lastReviewedAt)).length,missions=Object.values(s.missionProgress||{}).filter((row)=>isToday(row?.at)).length,fixed=s.mistakes.filter((row)=>isToday(row.resolvedAt)).length,lesson=activities.filter((row)=>row.type==="lesson").length;const checks=[reviews>0,lesson>0,missions>0,fixed>0||!s.mistakes.some((row)=>!row.resolved)];return{reviews,missions,fixed,lesson,checks,percent:Math.round(checks.filter(Boolean).length/checks.length*100)};}
  function nextStepPlan(){const snapshot=dailySnapshot(),due=dueCards(),openMistake=instance.state.mistakes.find((row)=>!row.resolved),lesson=ensureLesson(),reviewTarget=Math.min(3,due.length+snapshot.reviews);if(due.length&&snapshot.reviews<reviewTarget)return{kind:"review",tab:"practice",tool:"srs",icon:"復",label:`Ôn nhanh ${Math.min(3,due.length)} thẻ`,detail:"Mặt sau vẫn khóa cho tới khi bạn tự nhớ."};if(!snapshot.lesson)return{kind:"lesson",tab:"practice",tool:"lesson",icon:"習",label:`Tiếp tục từ ${lesson.index+1}/12`,detail:"Ngữ cảnh → nghe → hiểu → dùng trong câu."};if(openMistake&&!snapshot.fixed)return{kind:"mistake",tab:"practice",tool:"srs",icon:"誤",label:"Sửa một lỗi đang mở",detail:`${openMistake.category} · đã lặp ${openMistake.count} lần.`};if(!snapshot.missions){const mission=MISSIONS.find((row)=>!instance.state.missionProgress[row.id])||MISSIONS[0];return{kind:"mission",tab:"paths",missionId:mission.id,icon:mission.icon,label:mission.title,detail:`Can-do ${mission.jfLevel} · ${mission.context}`};}return{kind:"reader",tab:"immersion",icon:"読",label:"Kết thúc bằng một câu N+1",detail:"Đọc câu nguồn có tối đa một từ chưa biết."};}
  function nextStepDock(){const plan=nextStepPlan();return`<aside class="hhj6-next-dock" aria-label="Bước học tiếp theo"><span>${plan.icon}</span><div><small>BƯỚC TIẾP THEO ĐƯỢC TÍNH TỪ TIẾN ĐỘ THẬT</small><strong>${esc(plan.label)}</strong><p>${esc(plan.detail)}</p></div><button class="primary" data-hhj6-next-step>Tiếp tục →</button></aside>`;}
  function clearDictionaryFilters(resetQuery=false){if(resetQuery)instance.query="";instance.packFilter="all";instance.registerFilter="all";instance.levelFilter="all";instance.topicFilter="all";instance.posFilter="all";instance.searchIds=[];instance.localSearchIds=[];instance.searchDone=false;}
  function openVocabularyFacet(kind,value){clearDictionaryFilters(true);if(kind==="level")instance.levelFilter=value;if(kind==="topic")instance.topicFilter=value;if(kind==="pos")instance.posFilter=value;instance.wordId="";instance.state.lookupTool="dictionary";instance.state.activeTab="lookup";write();search("");}
  function followNextStep(){const plan=nextStepPlan();instance.state.activeTab=plan.tab;if(plan.tool)instance.state.practiceTool=plan.tool;if(plan.kind==="mission"&&plan.missionId){const mission=MISSIONS.find((row)=>row.id===plan.missionId);instance.missionId=plan.missionId;if(mission&&!mission.paths.includes(instance.state.path))instance.state.path=mission.track;const rows=MISSIONS.filter((row)=>row.paths.includes(instance.state.path)),index=rows.findIndex((row)=>row.id===plan.missionId);instance.missionPage=Math.max(0,Math.floor(Math.max(0,index)/20));}if(plan.kind==="reader"){instance.state.immersionId="bank";instance.sentenceIndex=0;}write();render();}

  function shell(content){const s=instance.state;return `<section class="hhj4-app">
    <header class="hhj4-top"><button data-hhj4-menu aria-label="Mở menu">☰</button><div class="hhj4-brand"><b>日</b><span><strong>HH Japanese OS</strong><small>V5 · Active Language Lab</small></span></div><nav>${MAIN_TABS.map(([id,label])=>`<button data-hhj4-tab="${id}" class="${s.activeTab===id?"active":""}">${label}</button>`).join("")}</nav><div class="hhj4-status"><span>${ALL_WORDS.length.toLocaleString("vi-VN")} từ · ${SENTENCES.length.toLocaleString("vi-VN")} câu</span><i>JLPT ${esc(s.jlptLevel)}</i><i>JF ${esc(s.jfLevel)}</i></div><button data-hhj4-profile>Hồ sơ ▾</button></header>
    <div class="hhj4-body"><aside class="hhj4-rail">${MAIN_TABS.map(([id,label,icon],index)=>`<button data-hhj4-tab="${id}" class="${s.activeTab===id?"active":""}"><i>${icon}</i><span>${label}</span><kbd>${index+1}</kbd></button>`).join("")}<footer><b>${s.streak} ngày</b><span>${s.xp} XP · tự lưu</span></footer></aside><main class="hhj4-main">${content}${nextStepDock()}</main></div>
    <div class="hhj4-toast" data-hhj4-toast role="status" hidden></div></section>`;}

  function todayView(){
    const s=instance.state,snapshot=dailySnapshot(),plan=nextStepPlan(),dueRows=dueCards(),quick=dueRows[0],nextMission=MISSIONS.find((row)=>!s.missionProgress[row.id])||MISSIONS[0],mistake=s.mistakes.find((row)=>!row.resolved),active=Object.values(s.vocabMastery).filter((row)=>row.mastered).length,useful=usefulVocabulary(6),sourceVietnamese=SENTENCES.filter((row)=>row.translationLanguage==="vie").length;
    const taskRows=[
      {icon:"復",title:"Ôn nhanh",detail:snapshot.reviews?`${snapshot.reviews} thẻ đã ôn hôm nay`:`${dueRows.length} thẻ đang đến hạn`,done:snapshot.reviews>0,action:`<button data-hhj4-open-practice="srs">${dueRows.length?"Ôn ngay":"Mở SRS"} →</button>`},
      {icon:"習",title:"Học theo bước",detail:snapshot.lesson?`${snapshot.lesson} bài đã hoàn thành`:`Từ ${ensureLesson().index+1}/12 · bước ${ensureLesson().step+1}/8`,done:snapshot.lesson>0,action:`<button data-hhj4-open-practice="lesson">Tiếp tục bài →</button>`},
      {icon:"話",title:"Can-do mission",detail:snapshot.missions?`${snapshot.missions} mission hôm nay`:`${nextMission.jfLevel} · ${nextMission.context}`,done:snapshot.missions>0,action:`<button data-hhj4-open-mission="${nextMission.id}">Mở mission →</button>`},
      {icon:"誤",title:"Sửa lỗi",detail:mistake?`${mistake.category} · sai ${mistake.count} lần`:"Không có lỗi đang mở",done:snapshot.fixed>0||!mistake,action:`<button data-hhj4-open-practice="srs">${mistake?"Sửa lỗi":"Xem notebook"} →</button>`}
    ];
    return `<section class="hhj4-view hhj4-today hhj6-cockpit"><header class="hhj4-hero hhj6-cockpit-hero"><div><small>LEARNING COCKPIT · ${day()}</small><h1>Biến dữ liệu có nguồn thành năng lực dùng được.</h1><p>Một bàn điều khiển cho học mới, ôn nhanh, sửa lỗi và đọc–nghe. JLPT, JF và vốn chủ động vẫn được đo độc lập.</p><div class="hhj6-hero-actions"><button class="primary" data-hhj6-next-step>${plan.icon} ${esc(plan.label)} →</button><button data-hhj4-tab="lookup">Tra kho 42K từ</button></div></div><div class="hhj4-ring"><strong>${snapshot.percent}%</strong><span>${snapshot.checks.filter(Boolean).length}/4 nhịp hôm nay</span></div></header>
      <section class="hhj6-flight-grid"><article class="hhj6-priority"><header><span>${plan.icon}</span><div><small>ƯU TIÊN TIẾP THEO</small><h2>${esc(plan.label)}</h2><p>${esc(plan.detail)}</p></div></header><div class="hhj6-stage-line">${taskRows.map((task,index)=>`<span class="${task.done?"done":index===taskRows.findIndex((row)=>!row.done)?"active":""}"><i>${task.done?"✓":index+1}</i><b>${task.title}</b></span>`).join("<em>→</em>")}</div><button class="primary" data-hhj6-next-step>Tiếp tục đúng bước →</button></article><aside class="hhj6-telemetry"><header><small>LIVE LEARNING STATE</small><strong>Tiến độ từ dữ liệu cục bộ</strong></header><div>${metric("Đến hạn",dueRows.length,"thẻ SRS")}${metric("Lỗi mở",s.mistakes.filter((row)=>!row.resolved).length,"Mistake Notebook")}${metric("Vốn chủ động",active,"đủ 3 năng lực")}${metric("Chuỗi",`${s.streak} ngày`,`${s.xp} XP`)}</div><footer><span><i></i> Hồ sơ ${esc(learnerId())}</span><small>Tự lưu · không bảng xếp hạng công khai</small></footer></aside></section>
      <section class="hhj6-operation-deck"><header><div><small>DAILY OPERATIONS</small><h2>Bốn nhịp học, không cần tìm đường</h2></div><span>${snapshot.checks.filter(Boolean).length}/4 hoàn thành</span></header><div>${taskRows.map((task)=>`<article class="${task.done?"done":""}"><i>${task.done?"✓":task.icon}</i><div><strong>${task.title}</strong><p>${esc(task.detail)}</p></div>${task.action}</article>`).join("")}</div></section>
      <section class="hhj6-quick-lane"><article class="hhj6-quick-review"><header><div><small>QUICK REVIEW · ĐÁP ÁN KHÓA</small><h2>${quick?esc(cardLabel(quick)):"Không còn thẻ đến hạn"}</h2><p>${quick?`${esc(cardStatus(quick))} · khoảng ${quick.interval||0} ngày`:"Bạn có thể lưu một từ hữu ích phía dưới để tạo thẻ mới."}</p></div><span>復</span></header>${quick?`<button class="hhj4-reveal-answer" data-hhj4-reveal-card="${esc(quick.id)}">Tự nhớ xong · hiện mặt sau</button><p hidden data-hhj4-card-answer="${esc(quick.id)}"></p><div class="hhj6-rating-row" hidden data-hhj4-card-ratings="${esc(quick.id)}">${[["forget","Quên"],["hard","Khó"],["remember","Nhớ"],["easy","Dễ"]].map(([id,label])=>`<button data-hhj4-rate="${id}" data-card="${esc(quick.id)}">${label}</button>`).join("")}</div>`:`<button data-hhj4-tab="lookup">Tìm từ để lưu →</button>`}</article><article class="hhj6-error-console"><header><div><small>ERROR NOTEBOOK</small><h2>${esc(mistake?.prompt||"Không có lỗi đang mở")}</h2><p>${mistake?`${esc(mistake.category)} · lặp ${mistake.count} lần · đáp án đang khóa`:"Lỗi từ lesson, trợ từ, shadowing và hội thoại sẽ tập trung tại đây."}</p></div><span>誤</span></header>${mistake?`<button class="hhj4-reveal-answer" data-hhj4-reveal-mistake="${esc(mistake.key)}">Hiện đáp án sau khi tự sửa</button><p hidden data-hhj4-mistake-answer="${esc(mistake.key)}"></p><button data-hhj4-resolve="${esc(mistake.key)}">Đánh dấu đã sửa</button>`:`<button data-hhj4-open-practice="srs">Mở Mistake Notebook →</button>`}</article></section>
      <section class="hhj6-vocab-radar"><header><div><small>VOCABULARY RADAR · DỮ LIỆU HIỆN CÓ</small><h2>Từ và cụm hữu ích theo mục tiêu hiện tại</h2><p>Chọn từ dữ liệu Việt đã biên tập/kiểm tra nguồn; mục JMdict nghĩa Anh vẫn giữ nguyên nhãn nguồn.</p></div><button data-hhj4-tab="lookup">Mở bộ lọc nâng cao →</button></header><nav aria-label="Lọc nhanh kho từ"><button data-hhj6-vocab-level="${esc(s.jlptLevel)}">JLPT ${esc(s.jlptLevel)}</button>${[...new Set(useful.map((row)=>row.topic).filter(Boolean))].slice(0,3).map((topic)=>`<button data-hhj6-vocab-topic="${esc(topic)}">${esc(topic)}</button>`).join("")}<button data-hhj6-vocab-pos="phrase">Cụm từ</button><button data-hhj6-vocab-pos="verb">Động từ</button></nav><div>${useful.map((row)=>{const status=statusOf(row);return`<article><button data-hhj6-open-word="${esc(row.id)}"><span><small>${esc(row.level||"N?")} · ${esc(row.topic||POS_GROUPS.find(([id])=>id===posGroup(row))?.[1]||"Từ vựng")}</small><strong>${esc(row.word)}</strong><i>${esc(row.kana)}</i></span><p>${esc(row.meaning)}</p><footer><b class="${status[1]}">${esc(status[0])}</b><small>${esc(row.source||"HH Japanese curated")}</small></footer></button></article>`;}).join("")}</div><footer><span>JMdict/EDRDG · Vietnamese source pack · checksum được giữ theo pack</span><small>${reviewedVietnamese().length.toLocaleString("vi-VN")} mục Việt · ${sourceVietnamese.toLocaleString("vi-VN")} câu dịch Việt</small></footer></section>
    </section>`;
  }

  function pathsView(){const s=instance.state,path=PATHS.find((row)=>row.id===s.path)||PATHS[1],rows=MISSIONS.filter((row)=>row.paths.includes(path.id)),selected=rows.find((row)=>row.id===instance.missionId)||rows[0],completed=rows.filter((row)=>s.missionProgress[row.id]).length,next=rows.find((row)=>!s.missionProgress[row.id]&&row.id!==selected.id);return `<section class="hhj4-view"><header class="hhj4-section-head"><div><small>FOUR PARALLEL PATHS</small><h1>Bốn lộ trình, một hồ sơ tiến độ</h1><p>Không quy đổi JLPT thành JF tuyệt đối; nói và viết được theo dõi riêng.</p></div><span>${completed}/${rows.length} mission</span></header><div class="hhj4-path-grid">${PATHS.map((row)=>`<button data-hhj4-path="${row.id}" class="${row.id===path.id?"active":""}" style="--path:${row.color}"><i>${row.icon}</i><strong>${row.title}</strong><span>${row.detail}</span></button>`).join("")}</div><div class="hhj4-workspace"><aside class="hhj4-list"><header><b>${path.title}</b><span>${rows.length} nhiệm vụ tự biên soạn</span></header>${rows.slice(instance.missionPage*20,instance.missionPage*20+20).map((row)=>`<button data-hhj4-mission="${row.id}" class="${row.id===selected.id?"active":""}"><i>${row.icon}</i><span><strong>${esc(row.title)}</strong><small>JF ${row.jfLevel} · ${esc(row.context)}</small></span>${s.missionProgress[row.id]?"✓":""}</button>`).join("")}<footer><button data-hhj4-mission-page="prev">‹</button><span>${instance.missionPage+1}/${Math.ceil(rows.length/20)}</span><button data-hhj4-mission-page="next">›</button></footer></aside><article class="hhj4-mission"><header><span>${selected.icon}</span><div><small>JF ${selected.jfLevel} · ${path.title}</small><h2>${esc(selected.title)}</h2><p>${esc(selected.variant)}</p></div></header><section><small>TÌNH HUỐNG</small><h3>${esc(selected.prompt)}</h3></section><section class="hhj4-answer" data-hhj4-mission-answer="${selected.id}"><small>CÂU MỤC TIÊU · KHÓA TRƯỚC KHI TỰ TRẢ LỜI</small><strong hidden aria-live="polite"></strong><button data-hhj4-reveal-mission="${selected.id}">Hiện câu mẫu sau khi tự trả lời</button><button hidden data-hhj4-speak>▶ Nghe câu mẫu</button><button hidden data-hhj4-save-sentence>＋ Lưu câu vào SRS</button></section><ol><li>Đọc tình huống và tự tạo câu</li><li>Hiện câu mẫu để đối chiếu</li><li>Nghe và nói lại theo cụm</li><li>Hoàn thành Can-do</li><li>Đưa câu yếu vào SRS</li></ol><footer>${next?`<button data-hhj6-next-mission="${next.id}">Mission kế tiếp</button>`:""}<button class="primary" data-hhj4-mission-complete="${selected.id}">${s.missionProgress[selected.id]?"✓ Đã hoàn thành":"Hoàn thành nhiệm vụ"}</button></footer><p class="hhj4-honesty">Nhiệm vụ HH tự biên soạn theo khung Can-do; không phải bài thi chính thức của Japan Foundation.</p></article></div></section>`;}

  function practiceView(){const tool=instance.state.practiceTool;return `<section class="hhj4-view"><header class="hhj4-section-head"><div><small>PRACTICE LAB V5</small><h1>Luyện một kỹ năng tại một thời điểm</h1><p>Chỉ đánh dấu chủ động khi người học nhận ra, nhớ lại và tự dùng được trong câu.</p></div></header><nav class="hhj4-subnav">${PRACTICE_TOOLS.map(([id,label,icon])=>`<button data-hhj4-practice="${id}" class="${tool===id?"active":""}"><i>${icon}</i>${label}</button>`).join("")}</nav>${tool==="lesson"?lessonView():tool==="active"?activeVocabularyView():tool==="particles"?particleLabView():tool==="shadowing"?shadowingView():tool==="writing"?writingView():tool==="srs"?srsView():tool==="grammar"?grammarView():tool==="mora"?moraView():conversationView()}</section>`;}
  function lessonView(){const lesson=ensureLesson(),ids=lesson.wordIds,row=effectiveWord(WORD_BY_ID.get(ids[lesson.index])||WORD_BY_ID.get(ids[0])),steps=["Ngữ cảnh","Nghe","Hiểu nghĩa","Collocation","Trợ từ","Nói lại","Tự tạo câu","Kiểm tra"],example=examplesForWord(row.word,1)[0],particle=example?particleNear(example.text,row.word):"",mastery=masteryOf(row.id),step=Math.max(0,Math.min(7,lesson.step||0));const content=[
    `<small>NGỮ CẢNH NGUỒN</small><h2>${esc(example?.text||row.word)}</h2><p>${esc(example?.translation||row.meaning)}</p>${example?`<a href="${example.sourceUrl}" target="_blank" rel="noopener">Tatoeba #${example.id} · ${esc(example.author)} · ${esc(example.license)}</a>`:"<span>Chưa tìm thấy câu phù hợp; dùng mục từ làm ngữ cảnh tối thiểu.</span>"}`,
    `<small>NGHE JA-JP</small><h2>${esc(example?.text||row.word)}</h2><button class="primary" data-hhj5-lesson-listen="${row.id}" data-hhj4-speak="${esc(example?.text||row.word)}">▶ Nghe mẫu</button><p>Audio thiết bị là fallback; không giả là giọng người thật.</p>`,
    `<small>NHẬP NGHĨA</small><h2>${esc(row.word)} · ${esc(row.kana)}</h2><form data-hhj5-lesson-meaning data-word="${row.id}"><input name="answer" autocomplete="off" placeholder="Nhập nghĩa tiếng Việt" required><button class="primary">Kiểm tra nghĩa</button></form>`,
    `<small>HỌC THEO CỤM</small><h2>${esc(row.word)}</h2><div class="hhj5-chip-list">${(row.related?.length?row.related:[`${row.word}を使う`,`${row.word}について話す`,`${row.word}が必要です`]).slice(0,8).map((item)=>`<button data-hhj5-lesson-collocation="${row.id}" data-hhj4-speak="${esc(item)}">${esc(item)}</button>`).join("")}</div><p>Chọn và nghe ít nhất một cụm để mở bước trợ từ. Cụm chưa kiểm duyệt vẫn giữ nhãn gợi ý.</p>`,
    `<small>TRỢ TỪ TRONG CÂU</small><h2>${esc(example?.text&&particle?example.text.replace(particle,"＿"):`${row.word} ＿`)}</h2><p>Chọn trợ từ phù hợp. Đáp án không được gắn vào nút hoặc hiển thị trước khi bạn trả lời.</p><div class="hhj5-chip-list">${[particle||"を","に","で","は","が","へ"].filter((x,i,a)=>a.indexOf(x)===i).map((item)=>`<button data-hhj5-lesson-particle="${esc(item)}" data-word="${row.id}">${esc(item)}</button>`).join("")}</div>`,
    `<small>SHADOWING NGẮN</small><h2>${esc(example?.text||row.word)}</h2><button class="primary" data-hhj5-lesson-record="${row.id}">● Nói lại và so transcript</button><p>Kết quả chỉ đo độ khớp transcript, trường âm, っ và ん.</p>`,
    `<small>TẠO CÂU MỚI</small><h2>Viết câu có ${esc(row.word)}</h2><form data-hhj5-lesson-production data-word="${row.id}"><textarea name="answer" lang="ja" required placeholder="${esc(row.word)}を使って文を書いてください。"></textarea><button class="primary">Kiểm tra & lưu</button></form>`,
    `<small>KẾT QUẢ TỪ</small><h2>${esc(row.word)} · ${esc(row.meaning)}</h2><div class="hhj4-metrics">${metric("Nhận diện",`${mastery.recognition}/5`,"Đọc/nghe")}${metric("Nhớ lại",`${mastery.recall}/5`,"Từ nghĩa sang Nhật")}${metric("Chủ động",`${mastery.production}/5`,"Tự dùng trong câu")}</div><p>${mastery.mastered?"✓ Đã đạt vốn chủ động.":"Cần tiếp tục ôn cả ba năng lực; hoàn thành một bài chưa đồng nghĩa đã thuộc."}</p>`
  ][step],canNext=step===0||step===7;return `<div class="hhj5-lesson"><aside><header><span><small>LESSON PLAYER V5</small><b>Bài 12 từ</b></span><span>${lesson.index+1}/${ids.length}</span></header>${ids.map((id,index)=>{const item=effectiveWord(WORD_BY_ID.get(id)),m=masteryOf(id);return`<button data-hhj5-lesson-word="${index}" class="${index===lesson.index?"active":""}"><span>${index+1}. ${esc(item?.word||id)}</span><i>${m.mastered?"✓":index<lesson.index?"•":""}</i></button>`;}).join("")}<button data-hhj5-new-lesson>↻ Tạo bài 12 từ mới</button></aside><article><nav>${steps.map((label,index)=>`<span class="${index===step?"active":index<step?"done":""}">${index+1}<small>${label}</small></span>`).join("")}</nav><section>${content}</section><footer><button data-hhj5-lesson-step="prev" ${step===0?"disabled":""}>← Trước</button><button class="primary" data-hhj5-lesson-step="next" ${canNext?"":"disabled"}>${step===7?lesson.index===ids.length-1?"Hoàn thành bài":"Từ tiếp theo →":step===0?"Bắt đầu nghe →":"Hoàn thành hoạt động trên"}</button></footer></article></div>`;}
  function nextActiveWord(){const current=instance.activeWordId&&WORD_BY_ID.get(instance.activeWordId);if(current)return effectiveWord(current);const rows=learningVocabulary(),row=rows.find((item)=>!masteryOf(item.id).mastered)||rows[0];instance.activeWordId=row?.id||"";return effectiveWord(row);}
  function activeVocabularyView(){const row=nextActiveWord(),mode=instance.activeMode||"recognition",m=masteryOf(row.id),pool=reviewedVietnamese().filter((item)=>item.id!==row.id).slice(0,3),choices=[row,...pool].sort((a,b)=>checksum(`${a.id}:${row.id}`).localeCompare(checksum(`${b.id}:${row.id}`)));return `<div class="hhj5-active"><header><div><small>ACTIVE VOCABULARY</small><h2>${mode==="recognition"?row.word:row.meaning}</h2><p>${mode==="recognition"?`${row.kana} · chọn nghĩa đúng`:mode==="recall"?"Gõ từ tiếng Nhật phù hợp":"Tự viết một câu dùng từ này"}</p></div><div>${metric("Nhận diện",m.recognition,"/5")}${metric("Nhớ lại",m.recall,"/5")}${metric("Chủ động",m.production,"/5")}</div></header><nav>${[["recognition","Nhận diện"],["recall","Nhớ lại"],["production","Chủ động"]].map(([id,label])=>`<button data-hhj5-active-mode="${id}" class="${mode===id?"active":""}">${label}</button>`).join("")}</nav>${mode==="recognition"?`<section class="hhj5-answer-grid">${choices.map((item)=>`<button data-hhj5-active-answer="${esc(item.id)}" data-word="${row.id}" data-skill="recognition">${esc(item.meaning)}</button>`).join("")}</section>`:`<form data-hhj5-active-form data-word="${row.id}" data-skill="${mode}"><textarea name="answer" lang="ja" required placeholder="${mode==="recall"?"Nhập từ Nhật":"Viết một câu tiếng Nhật"}"></textarea><button class="primary">Kiểm tra</button></form>`}<footer><button data-hhj5-active-next>Từ khác →</button><span>${m.mastered?"✓ Vốn chủ động":"Chưa đạt đủ ba năng lực"}</span></footer></div>`;}
  function particleLabView(){const lab=PARTICLE_LABS.find((row)=>row.id===instance.particleId)||PARTICLE_LABS[0],stats=instance.state.particleStats[lab.id]||{correct:0,total:0};return `<div class="hhj4-practice-layout"><aside class="hhj4-list">${PARTICLE_LABS.map((row)=>`<button data-hhj5-particle-lab="${row.id}" class="${row.id===lab.id?"active":""}"><i>助</i><span><strong>${row.title}</strong><small>${esc(row.rule)}</small></span></button>`).join("")}</aside><article class="hhj5-particles"><small>USAGE & PARTICLE LAB</small><h2>${lab.title}</h2><p>${lab.rule}</p><header><span>Đúng ${stats.correct}/${stats.total}</span></header>${lab.questions.map((question,qIndex)=>`<section><h3>${esc(question.text)}</h3><div>${question.options.map((option)=>`<button data-hhj5-particle-answer="${esc(option)}" data-lab="${lab.id}" data-question="${qIndex}">${esc(option)}</button>`).join("")}</div></section>`).join("")}</article></div>`;}
  function shadowingView(){const row=SENTENCE_BY_ID.get(String(instance.shadowSentenceId))||SENTENCES.find((item)=>item.translationLanguage==="vie")||SENTENCES[0],result=instance.shadowResult;return `<article class="hhj5-shadow"><header><div><small>AUDIO & SHADOWING V2</small><h2>${esc(row.text)}</h2><p>${esc(row.translation)}</p><span>Tatoeba #${row.id} · ${esc(row.author)} · ${esc(row.license)}</span></div><button data-hhj5-shadow-next>Câu khác →</button></header><div class="hhj5-wave"><canvas width="900" height="150" data-hhj5-wave aria-label="Waveform bản ghi"></canvas></div><div class="hhj4-speech-actions"><button data-hhj4-speak="${esc(row.text)}">1. Nghe mẫu</button><button class="primary" data-hhj5-shadow-record="${row.id}">2. Ghi âm & so sánh</button>${result?.audioUrl?`<audio controls src="${result.audioUrl}"></audio>`:""}</div>${result?`<section class="hhj4-speech-result"><div>${metric("Transcript",`${result.match}%`,"Không phải điểm phát âm")}${metric("Tốc độ",result.speed,"ký tự/giây")}${metric("Mora thiếu",result.missing,"ước tính ký tự")}${metric("っ・ー・ん",result.special,"tín hiệu bị thiếu")}</div><p><b>Nhận được:</b> ${esc(result.transcript||"Không có transcript")}</p></section>`:""}<p>Không chấm pitch hoặc phoneme khi trình duyệt không cung cấp dữ liệu tương ứng.</p></article>`;}
  function conversationView(){const scenario=CONVERSATIONS.find((row)=>row.id===instance.conversationId)||CONVERSATIONS[0],result=instance.conversationResult;return `<div class="hhj4-practice-layout"><aside class="hhj4-list">${CONVERSATIONS.map((row)=>`<button data-hhj4-conversation="${row.id}" class="${row.id===scenario.id?"active":""}"><i>${row.icon}</i><span><strong>${row.title}</strong><small>${row.prompt}</small></span></button>`).join("")}</aside><article class="hhj4-simulator"><header><span>${scenario.icon}</span><div><small>CONVERSATION SIMULATOR</small><h2>${scenario.title}</h2><p>${scenario.prompt}</p></div></header><section class="hhj4-dialogue"><p><b>Đối phương</b>${esc(scenario.prompt)}</p><div>${scenario.options.map((option,index)=>`<button data-hhj4-response="${index}" data-scenario="${scenario.id}">${esc(option.text)}</button>`).join("")}</div></section><div class="hhj4-speech-actions"><button data-hhj4-speak="${esc(scenario.expected)}">1. Nghe mẫu</button><button class="primary" data-hhj4-record="${scenario.id}">2. Nói lại</button><button data-hhj4-save-sentence="${esc(scenario.expected)}">3. Lưu vào SRS</button></div>${result?`<section class="hhj4-speech-result"><h3>Kết quả gần nhất</h3><div>${metric("Transcript",`${result.match}%`,"Độ khớp văn bản")}${metric("Tốc độ",result.speed,"Ước tính ký tự/giây")}${metric("Mora thiếu",result.missing,"So độ dài, không chấm phoneme")}${metric("Trường âm/っ",result.special,"Tín hiệu ký tự")}</div><p><b>Bạn nói:</b> ${esc(result.transcript)}</p><small>Đây không phải điểm phát âm hoặc pitch accent.</small></section>`:""}</article></div>`;}
  function writingView(){const task=WRITING_TASKS.find((row)=>row.id===instance.writingId)||WRITING_TASKS[0],latest=instance.writingResult;return `<div class="hhj4-practice-layout"><aside class="hhj4-list">${WRITING_TASKS.map((row)=>`<button data-hhj4-writing="${row.id}" class="${row.id===task.id?"active":""}"><i>書</i><span><strong>${row.label}</strong><small>${row.prompt}</small></span></button>`).join("")}</aside><article class="hhj4-writing"><header><small>WRITING STUDIO</small><h2>${task.label}</h2><p>${task.prompt}</p></header>${["kana","kanji"].includes(task.id)?`<section class="hhj4-pad"><canvas width="900" height="360" data-hhj4-pad aria-label="Bảng luyện viết"></canvas><button data-hhj4-pad-clear>Xóa bảng</button><span>Hướng dẫn trực quan; chưa tự tuyên bố nhận dạng đúng nét khi chưa có KanjiVG tương ứng.</span></section>`:""}<form data-hhj4-writing-form data-task="${task.id}"><textarea name="text" lang="ja" maxlength="1600" placeholder="${esc(task.sample)}" required></textarea><button class="primary">Kiểm tra & lưu lỗi</button></form>${latest?`<section class="hhj4-diff"><div><small>BẢN GỐC</small><p>${esc(latest.original)}</p></div><div><small>GỢI Ý</small><p>${esc(latest.suggestion)}</p></div><footer>${latest.issues.map(esc).join(" · ")||"Không phát hiện lỗi quy tắc cục bộ; vẫn cần người có chuyên môn duyệt sắc thái."}</footer></section>`:""}</article></div>`;}
  function cardLabel(card){if(card.type==="word"){const row=WORD_BY_ID.get(card.ref);return row?row.word:card.ref;}return card.payload?.prompt||card.ref;}
  function cardAnswer(card){if(card.type==="word"){const row=WORD_BY_ID.get(card.ref);return row?`${row.kana||""} · ${row.meaning}`:"Chưa có nghĩa đã kiểm duyệt";}return card.payload?.correct||card.payload?.text||"Chưa có đáp án đã lưu";}
  function srsView(){const rows=dueCards().slice(0,40);return `<article class="hhj4-srs"><header><div><small>SRS V3</small><h2>${rows.length} thẻ cần xử lý</h2><p>Từ vựng · collocation · câu · ngữ pháp · nghe–chép. Mặt sau luôn khóa trước khi tự nhớ.</p></div><div class="hhj4-state-legend">${["new","learning","due","hard","mastered","relearning"].map((x)=>`<span>${x}</span>`).join("")}</div></header>${rows.length?`<div class="hhj4-card-list">${rows.map((card)=>`<article><span>${esc(card.type)}</span><h3>${esc(cardLabel(card))}</h3><small>${cardStatus(card)} · ${card.interval||0} ngày · quên ${card.lapses||0}</small><button class="hhj4-reveal-answer" data-hhj4-reveal-card="${esc(card.id)}">Hiện đáp án</button><p hidden data-hhj4-card-answer="${esc(card.id)}"></p><div hidden data-hhj4-card-ratings="${esc(card.id)}">${[["forget","Quên"],["hard","Khó"],["remember","Nhớ"],["easy","Dễ"]].map(([id,label])=>`<button data-hhj4-rate="${id}" data-card="${esc(card.id)}">${label}</button>`).join("")}</div></article>`).join("")}</div>`:`<div class="hhj4-empty"><b>Không còn thẻ đến hạn</b><p>Lưu từ, câu hoặc lỗi mới để tiếp tục SRS.</p></div>`}<section class="hhj4-mistakes"><header><h3>Mistake Notebook</h3><span>${instance.state.mistakes.filter(x=>!x.resolved).length} lỗi mở</span></header>${instance.state.mistakes.filter(x=>!x.resolved).slice(0,20).map((row)=>`<article><b>${esc(row.category)}</b><span>${esc(row.prompt)}</span><small>Đã sai ${row.count} lần · đáp án đang khóa</small><button class="hhj4-reveal-answer" data-hhj4-reveal-mistake="${esc(row.key)}">Hiện đáp án lỗi</button><p hidden data-hhj4-mistake-answer="${esc(row.key)}"></p><button data-hhj4-resolve="${esc(row.key)}">Đã sửa</button></article>`).join("")||"<p>Chưa có lỗi.</p>"}</section></article>`;}
  function grammarView(){const rows=v3?.contrasts||[],selected=rows.find((row)=>row.id===instance.grammarId)||rows[0];if(!selected)return`<div class="hhj4-empty">Chưa có dữ liệu Grammar Contrast.</div>`;return `<div class="hhj4-practice-layout"><aside class="hhj4-list">${rows.map((row)=>`<button data-hhj4-grammar="${row.id}" class="${row.id===selected.id?"active":""}"><i>文</i><span><strong>${esc(row.title)}</strong><small>${row.level}</small></span></button>`).join("")}</aside><article class="hhj4-lesson"><small>GRAMMAR CONTRAST</small><h2>${esc(selected.title)}</h2><p>${esc(selected.rule)}</p><div class="good">✓ ${esc(selected.good)}</div><div class="bad">× ${esc(selected.bad)}</div><button data-hhj4-save-grammar="${selected.id}">＋ Lưu cấu trúc vào SRS</button></article></div>`;}
  function moraView(){const rows=v3?.mora||[],selected=rows.find((row)=>row.id===instance.moraId)||rows[0],result=instance.moraResult;if(!selected)return`<div class="hhj4-empty">Chưa có dữ liệu Mora.</div>`;return `<div class="hhj4-practice-layout"><aside class="hhj4-list">${rows.map((row)=>`<button data-hhj4-mora="${row.id}" class="${row.id===selected.id?"active":""}"><i>音</i><span><strong>${esc(row.label)}</strong><small>${esc(row.parts)}</small></span></button>`).join("")}</aside><article class="hhj4-lesson"><small>SHADOWING & MORA</small><h2>${esc(selected.label)}</h2><strong class="japanese">${esc(selected.sample)}</strong><p>${esc(selected.tip)}</p><div class="hhj4-speech-actions"><button data-hhj4-speak="${esc(selected.sample)}">Nghe mẫu</button><button data-hhj4-record-mora="${selected.id}">Ghi & so transcript</button><button data-hhj4-save-sentence="${esc(selected.sample)}">Lưu câu</button></div>${result&&result.id===selected.id?`<section class="hhj4-speech-result"><b>Khớp transcript ${result.match}%</b><p>${esc(result.transcript)}</p><small>${esc(result.note)}</small></section>`:""}<small>Không chấm pitch/phoneme nếu trình duyệt chỉ trả transcript.</small></article></div>`;}

  function lookupView(){const tool=instance.state.lookupTool;return `<section class="hhj4-view"><header class="hhj4-section-head"><div><small>LOOKUP & DATA V5</small><h1>42K từ và 30K câu trong một workspace</h1><p>Tìm kiếm chạy cục bộ; mỗi câu và mục từ giữ nguồn, trạng thái và giấy phép riêng.</p></div></header><nav class="hhj4-subnav">${LOOKUP_TOOLS.map(([id,label])=>`<button data-hhj4-lookup="${id}" class="${tool===id?"active":""}">${label}</button>`).join("")}</nav>${tool==="sentences"?sentenceBankView():tool==="packs"?packsView():tool==="kanji"?kanjiView():tool==="utilities"?utilitiesView():dictionaryView()}</section>`;}
  function sentenceRows(){const q=String(instance.sentenceQuery||"").normalize("NFKC").toLocaleLowerCase("ja");return SENTENCES.filter((row)=>(!q||`${row.text} ${row.translation}`.toLocaleLowerCase("ja").includes(q))&&(instance.sentenceTopic==="all"||!instance.sentenceTopic||row.topic===instance.sentenceTopic)&&(instance.sentenceLanguage==="all"||!instance.sentenceLanguage||row.translationLanguage===instance.sentenceLanguage)).slice(0,300);}
  function sentenceBankView(){const rows=sentenceRows(),selected=SENTENCE_BY_ID.get(String(instance.sentenceId))||rows[0],unknown=selected?unknownSentenceWords(selected):[],status=selected?sentenceStatus(selected):{};return `<div class="hhj4-workspace"><aside class="hhj4-list hhj5-sentence-list"><form data-hhj5-sentence-search><input name="query" value="${esc(instance.sentenceQuery||"")}" placeholder="Tìm câu Nhật hoặc bản dịch"><button>Tìm</button></form><div class="hhj4-filters"><select data-hhj5-sentence-topic><option value="all">Mọi chủ đề</option>${["general","life","career","health","travel","food","school"].map((topic)=>`<option value="${topic}" ${instance.sentenceTopic===topic?"selected":""}>${topic}</option>`).join("")}</select><select data-hhj5-sentence-language><option value="all">Việt + Anh</option><option value="vie" ${instance.sentenceLanguage==="vie"?"selected":""}>Tiếng Việt</option><option value="eng" ${instance.sentenceLanguage==="eng"?"selected":""}>Tiếng Anh</option></select></div><header><b>${rows.length} kết quả đầu</b><span>${SENTENCES.length.toLocaleString("vi-VN")} câu nguồn</span></header><div class="hhj4-scroll-list">${rows.map((row)=>`<button data-hhj5-sentence="${row.id}" class="${selected?.id===row.id?"active":""}"><span><strong>${esc(row.text)}</strong><small>${esc(row.translation)}</small></span><i>${row.level}</i></button>`).join("")||"<p>Không có câu phù hợp.</p>"}</div></aside>${selected?`<article class="hhj5-sentence-detail"><header><div><small>${selected.reviewStatus==="source-filtered"?"ĐÃ LỌC NGUỒN · CHƯA BIÊN TẬP":"ĐÃ KIỂM DUYỆT"}</small><h2>${esc(selected.text)}</h2><p>${esc(selected.translation)}</p></div><button data-hhj4-speak="${esc(selected.text)}">▶ Nghe</button></header><div class="hhj4-data-grid">${metric("Độ phủ",`${Math.max(0,100-Math.round(unknown.length/Math.max(1,tokenize(selected.text).filter(x=>x.row).length)*100))}%`,`${unknown.length} từ chưa biết`)}${metric("N+1",unknown.length<=1?"Phù hợp":"Chưa phù hợp","Tối đa một từ mới")}${metric("Nguồn",`Tatoeba #${selected.id}`,`${selected.author} · ${selected.license}`)}${metric("Bản dịch",selected.translationLanguage==="vie"?"Tiếng Việt":"Tiếng Anh",`${selected.translationAuthor} · ${selected.translationLicense}`)}</div><section class="hhj4-token-line">${tokenize(selected.text).map((token)=>token.row?`<button data-hhj4-reader-word="${token.row.id}" class="${instance.state.knownWords[token.row.id]?"known":""}">${esc(token.text)}<small>${esc(token.row.kana)}</small></button>`:esc(token.text)).join("")}</section><section><h3>Từ chưa biết</h3><div class="hhj5-chip-list">${unknown.map((row)=>`<button data-hhj4-save-word="${row.id}">${esc(row.word)} · ${esc(row.meaning)}</button>`).join("")||"<span>Không có từ mới theo tokenizer hiện tại.</span>"}</div></section><footer><a href="${selected.sourceUrl}" target="_blank" rel="noopener">Xem nguồn & ghi công</a><button data-hhj5-save-dictation="${selected.id}">＋ Nghe–chép SRS</button><button class="primary" data-hhj5-save-sentence="${selected.id}">${status.saved?"★ Đã lưu":"☆ Lưu cả câu"}</button></footer></article>`:`<article class="hhj4-empty">Chọn một câu.</article>`}</div>`;}
  function dictionaryRows(){let rows=instance.searchDone?instance.searchIds.map((id)=>WORD_BY_ID.get(id)).filter(Boolean):ALL_WORDS;if(instance.packFilter!=="all")rows=rows.filter((row)=>instance.packFilter==="vi-core"?row.meaningLanguage==="vi":row.packId===instance.packFilter);if(instance.registerFilter!=="all")rows=rows.filter((row)=>row.register===instance.registerFilter);return rows.filter(dictionaryFacetMatch).slice(0,160);}
  function dictionaryView(){const rows=dictionaryRows(),selected=rows.find((row)=>row.id===instance.wordId)||rows[0],facets=vocabularyFacets(),activeFilters=[instance.packFilter,instance.registerFilter,instance.levelFilter,instance.topicFilter,instance.posFilter].filter((value)=>value!=="all").length;return `<div class="hhj4-workspace hhj6-dictionary-workspace"><aside class="hhj4-list hhj4-dictionary hhj6-dictionary"><form data-hhj4-search><input name="query" value="${esc(instance.query)}" placeholder="Kanji, Kana, Romaji, Việt/Anh"><button>Tìm</button></form><div class="hhj6-dictionary-filter-head"><span><b>Bộ lọc dữ liệu thật</b><small>${activeFilters} bộ lọc · ${rows.length} kết quả đang hiển thị</small></span><button type="button" data-hhj6-clear-vocab-filters>Xóa lọc</button></div><div class="hhj4-filters hhj6-dictionary-filters"><label><span>Nguồn/gói</span><select name="pack" data-hhj4-pack-filter><option value="all">Tất cả gói</option>${packCatalog().map((pack)=>`<option value="${pack.id}" ${instance.packFilter===pack.id?"selected":""}>${pack.label}</option>`).join("")}</select></label><label><span>JLPT metadata</span><select data-hhj6-level-filter><option value="all">Mọi cấp</option>${facets.levels.map(([id,count])=>`<option value="${id}" ${instance.levelFilter===id?"selected":""}>${id} · ${count.toLocaleString("vi-VN")}</option>`).join("")}</select></label><label><span>Chủ đề</span><select data-hhj6-topic-filter><option value="all">Mọi chủ đề</option>${facets.topics.map(([id,count])=>`<option value="${esc(id)}" ${instance.topicFilter===id?"selected":""}>${esc(id)} · ${count.toLocaleString("vi-VN")}</option>`).join("")}</select></label><label><span>Từ loại</span><select data-hhj6-pos-filter><option value="all">Mọi từ loại</option>${facets.parts.map(([id,label,count])=>`<option value="${id}" ${instance.posFilter===id?"selected":""}>${label} · ${count.toLocaleString("vi-VN")}</option>`).join("")}</select></label><label><span>Sắc thái</span><select data-hhj4-register><option value="all">Mọi sắc thái</option>${["trung tính","lịch sự/kính ngữ","văn viết/trang trọng","khẩu ngữ/thân mật","công việc/chuyên ngành"].map((row)=>`<option ${instance.registerFilter===row?"selected":""}>${row}</option>`).join("")}</select></label></div><p class="hhj6-filter-honesty">N5–N1 chỉ dùng metadata đã có trong từng pack; mục JMdict không xác minh giữ nhãn N? và không bị tự gán cấp.</p><div class="hhj4-scroll-list">${rows.map((row)=>{const status=statusOf(row);return`<button data-hhj4-word="${row.id}" class="${selected?.id===row.id?"active":""}"><span><strong>${esc(row.word)}</strong><small>${esc(row.kana)} · ${esc(row.meaning)}</small><em>${esc(row.topic||POS_GROUPS.find(([id])=>id===posGroup(row))?.[1]||"Chưa gắn chủ đề")}</em></span><i class="${status[1]}">${row.level||"N?"}</i></button>`;}).join("")||"<p>Không tìm thấy mục phù hợp. Hãy xóa bớt bộ lọc hoặc đổi từ khóa.</p>"}</div></aside>${selected?wordDetail(selected):`<article class="hhj4-empty"><b>Không có mục phù hợp</b><p>Bộ lọc không tự nới lỏng để tránh hiển thị sai phạm vi bạn chọn.</p><button data-hhj6-clear-vocab-filters>Xóa toàn bộ bộ lọc</button></article>`}</div>`;}
  function wordDetail(sourceRow){const row=effectiveWord(sourceRow),[status,tone]=statusOf(row),saved=instance.state.cards.some((card)=>card.id===`word:${row.id}`),kanji=[...row.word].filter((char)=>/[\u3400-\u9fff]/.test(char)),examples=examplesForWord(row.word,4),mastery=masteryOf(row.id);return `<article class="hhj4-word-detail"><header><div><small class="${tone}">${esc(row.reviewStatus==="reviewed-local"?"Đã duyệt trong hồ sơ":status)}</small><h2>${esc(row.word)}</h2><p>${esc(row.kana)} · ${esc(row.romaji||"Chưa có Romaji")}</p></div><button data-hhj4-speak="${esc(row.word)}">▶ Nghe ja-JP</button></header><section><span>${esc(row.pos||"Chưa phân loại")}</span><h3>${esc(row.meaning)}</h3><p>${row.meaningLanguage==="en"?"Nghĩa Anh tham chiếu từ JMdict; chưa tự dịch sang Việt.":"Nghĩa Việt có nguồn/biên tập; trạng thái được hiển thị riêng."}</p></section><div class="hhj4-data-grid"><article><small>VỐN CHỦ ĐỘNG</small><b>${mastery.recognition}/${mastery.recall}/${mastery.production}</b><span>Nhận diện · nhớ lại · tự dùng</span></article><article><small>SẮC THÁI</small><b>${esc(row.register||"Chưa xác minh")}</b><span>${esc(row.conjugationType||"Không áp dụng")}</span></article><article><small>TRỢ TỪ & COLLOCATION</small><b>${row.particles?.length?row.particles.map(esc).join(" · "):"Chưa xác minh"}</b><span>${row.related?.length?`Liên quan: ${row.related.map(esc).join(" · ")}`:"Chưa có dữ liệu liên kết."}</span></article><article><small>JLPT / PITCH</small><b>${row.jlptVerified?row.level:"Chưa xác minh"}</b><span>${row.pitchVerified?esc(row.pitch):"Không tự gán pitch accent."}</span></article><article><small>KANJI</small><b>${kanji.map(esc).join(" · ")||"Không có Kanji"}</b><span>${kanji.filter(x=>STROKES[x]).length}/${kanji.length} có stroke KanjiVG.</span></article><article><small>NGUỒN</small><b>${esc(row.source||"HH Japanese curated")}</b><span>${esc(row.license||"Nội dung HH tự biên soạn")} · ${checksum(JSON.stringify(row))}</span></article></div>${examples.length?`<section class="hhj5-word-examples"><h3>Câu nguồn</h3>${examples.map((item)=>`<button data-hhj5-sentence="${item.id}"><b>${esc(item.text)}</b><span>${esc(item.translation)}</span><small>${esc(item.author)} · ${esc(item.license)}</small></button>`).join("")}</section>`:""}<footer><button data-hhj4-known="${row.id}" class="${instance.state.knownWords[row.id]?"active":""}">✓ Đã biết</button><button data-hhj5-review-word="${row.id}">Đề xuất chỉnh sửa</button><button class="primary" data-hhj4-save-word="${row.id}">${saved?"★ Đã có trong SRS":"☆ Thêm vào SRS"}</button></footer></article>`;}
  function packsView(){return `<div class="hhj4-pack-view"><header><div><small>OFFLINE PACK MANAGER V5</small><h2>${ALL_WORDS.length.toLocaleString("vi-VN")} từ · ${SENTENCES.length.toLocaleString("vi-VN")} câu · ${strokePack.count.toLocaleString("vi-VN")} Kanji</h2></div><span>Version + checksum + rollback</span></header><div class="hhj4-pack-grid">${packCatalog().map((pack)=>{const pct=Math.min(100,Math.round(pack.count/pack.target*100)),saved=instance.state.offlinePacks[pack.id],description=pack.id==="vi-core"?"Nghĩa Việt; tách rõ đã kiểm duyệt và dữ liệu nguồn mở.":pack.id==="sentences-v5"?"Tatoeba: tác giả và giấy phép theo từng câu; audio chưa xác minh để trống.":pack.id==="kanjivg-v5"?"Stroke SVG KanjiVG theo CC BY-SA 3.0.":"Nguồn mở JMdict; nghĩa Anh tham chiếu, không tự gán JLPT.";return`<article><header><b>${pack.label}</b><span>${pack.count.toLocaleString("vi-VN")} / mục tiêu ${pack.target.toLocaleString("vi-VN")}</span></header><progress max="100" value="${pct}"></progress><p>${description}</p><footer><small>${saved?`Offline ${saved.count.toLocaleString("vi-VN")} mục · ${saved.at.slice(0,10)}`:"Chưa lưu offline"}</small><button data-hhj4-offline="${pack.id}">${saved?"Tạo snapshot mới":"Tải offline"}</button></footer></article>`;}).join("")}</div><section class="hhj4-career"><header><h3>Career Packs</h3><span>Phân loại theo field của JMdict</span></header>${careerCatalog().map((row)=>`<article><b>${row.label}</b><span>${row.count.toLocaleString("vi-VN")} thuật ngữ nguồn mở</span></article>`).join("")}</section></div>`;}
  function kanjiView(){const chars=Object.keys(STROKES),char=STROKES[instance.kanjiChar]?instance.kanjiChar:(chars[0]||"日"),stroke=STROKES[char],legacyItem=(legacy.kanji||[]).find((row)=>row.char===char),words=ALL_WORDS.filter((row)=>row.word?.includes(char)).slice(0,12),start=Math.max(0,instance.kanjiPage||0)*80,visible=chars.slice(start,start+80);return `<div class="hhj4-kanji hhj5-kanji"><aside class="hhj4-list"><form data-hhj5-kanji-search><input name="char" maxlength="1" value="${esc(char)}" placeholder="Kanji"><button>Mở</button></form><header><b>${strokePack.count.toLocaleString("vi-VN")} KanjiVG</b><span>CC BY-SA 3.0</span></header><div class="hhj5-kanji-grid">${visible.map((value)=>`<button data-hhj4-kanji="${value}" class="${value===char?"active":""}">${value}</button>`).join("")}</div><footer><button data-hhj5-kanji-page="prev">‹</button><span>${start+1}–${Math.min(chars.length,start+80)}</span><button data-hhj5-kanji-page="next">›</button></footer></aside><article><header><strong>${char}</strong><div><small>KANJI WRITING V2 · ${stroke?.paths.length||0} NÉT</small><h2>${legacyItem?.meanings?.map(esc).join(" · ")||words.slice(0,4).map((row)=>esc(row.meaning)).join(" · ")||"Chưa có nghĩa Việt đã duyệt"}</h2></div></header><div class="hhj4-graph"><span>Radical<b>${esc(legacyItem?.radical||"Chưa nạp")}</b></span><span>Onyomi<b>${legacyItem?.on?.map(esc).join("、")||"—"}</b></span><span>Kunyomi<b>${legacyItem?.kun?.map(esc).join("、")||"—"}</b></span><span>Từ chứa Kanji<b>${words.slice(0,5).map((row)=>esc(row.word)).join(" · ")||"—"}</b></span></div><section class="hhj5-stroke-stage"><svg viewBox="0 0 109 109" data-hhj5-stroke-svg aria-label="Thứ tự nét ${char}">${stroke?.paths.map((d,index)=>`<path d="${esc(d)}" data-stroke="${index}" style="--i:${index}"></path>`).join("")||""}</svg><div><button class="primary" data-hhj5-play-strokes>▶ Phát thứ tự nét</button><button data-hhj5-stroke-step="prev">← Nét trước</button><button data-hhj5-stroke-step="next">Nét sau →</button><span data-hhj5-stroke-label>Nét 1/${stroke?.paths.length||0}</span></div></section><section class="hhj4-pad"><canvas width="420" height="420" data-hhj4-pad aria-label="Bảng luyện theo nét"></canvas><div><button data-hhj4-pad-clear>Xóa bảng</button><span data-hhj5-stroke-status>Vẽ nét 1 theo hướng dẫn.</span></div></section><section class="hhj5-chip-list">${words.map((row)=>`<button data-hhj4-word="${row.id}">${esc(row.word)} · ${esc(row.kana)}</button>`).join("")}</section><p class="hhj4-honesty">Stroke: KanjiVG · CC BY-SA 3.0 · ${strokePack.checksum?.slice(0,12)}… Kiểm tra hướng chỉ là hình học gần đúng, không phải nhận dạng chữ viết tay tuyệt đối.</p></article></div>`;}
  function utilitiesView(){return `<div class="hhj4-utilities"><article><small>KANA CONVERTER</small><h3>Romaji → Hiragana → Katakana</h3><form data-hhj4-kana><input name="text" placeholder="nihongo" required><button>Chuyển</button><output></output></form></article><article><small>VERB CONJUGATOR</small><h3>Chia động từ cục bộ</h3><form data-hhj4-conjugate><input name="verb" placeholder="食べる" required><button>Chia</button><output></output></form></article><article><small>IMPORT / EXPORT</small><h3>Dữ liệu cá nhân</h3><div><button data-hhj4-export="json">JSON</button><button data-hhj4-export="anki">Anki TSV</button><label>Nhập JSON<input type="file" accept="application/json,.json" data-hhj4-import></label></div></article></div>`;}

  function tokenize(text){const tokens=[];let at=0;while(at<text.length){let hit=null;for(let length=Math.min(MAX_SURFACE,text.length-at);length>0;length--){const value=text.slice(at,at+length);if(SURFACE.has(value)){hit=SURFACE.get(value);break;}}if(hit){tokens.push({text:hit.word,row:hit});at+=hit.word.length;}else{tokens.push({text:text[at],row:null});at++;}}return tokens;}
  function immersionView(){const s=instance.state,item=IMMERSION.find((row)=>row.id===s.immersionId)||IMMERSION[0];let sentences;if(instance.customText&&item.id==="subtitle")sentences=instance.customText.split(/(?<=[。！？\n])/u).map((row)=>row.trim()).filter(Boolean).slice(0,80).map((row)=>[row,"Văn bản do người học nhập · chưa có bản dịch",null]);else if(item.id==="bank")sentences=nPlusOneSentences(80).map(({row})=>[row.text,row.translation,row]);else sentences=item.sentences.map(([jp,vi])=>[jp,vi,null]);const sentence=sentences[instance.sentenceIndex]||sentences[0]||["文章を入力してください。","Hãy nhập văn bản.",null],sourceSentence=sentence[2],tokens=tokenize(sentence[0]),selected=effectiveWord(WORD_BY_ID.get(instance.readerWordId)),known=tokens.filter(x=>x.row&&s.knownWords[x.row.id]).length,total=tokens.filter(x=>x.row).length,unknown=sourceSentence?unknownSentenceWords(sourceSentence):[];return `<section class="hhj4-view"><header class="hhj4-section-head"><div><small>SMART READER V3</small><h1>Đọc câu n+1 và biến lỗi thành bài ôn</h1><p>Tách từ, dạng từ điển, Furigana thích ứng, độ phủ và nghe–chép dùng chung một câu nguồn.</p></div><button data-hhj4-furigana>${s.furigana?"Ẩn Furigana từ đã thuộc":"Hiện Furigana"}</button></header><div class="hhj4-immersion"><aside class="hhj4-list">${IMMERSION.map((row)=>`<button data-hhj4-immersion="${row.id}" class="${row.id===item.id?"active":""}"><i>${row.icon}</i><span><strong>${row.title}</strong><small>${row.level} · ${row.id==="bank"?`${SENTENCES.length.toLocaleString("vi-VN")} câu có license`:"nội dung HH tự biên soạn"}</small></span></button>`).join("")}<button data-hhj4-custom-text>＋ Dán văn bản/subtitle</button></aside><article class="hhj4-reader"><header><small>${item.level} · ${item.title} ${sourceSentence?`· Tatoeba #${sourceSentence.id}`:""}</small><h2>${sentence[0]}</h2><p>${sentence[1]}</p><div><button data-hhj4-speak="${esc(sentence[0])}">▶ Nghe câu</button>${sourceSentence?`<button data-hhj5-save-dictation="${sourceSentence.id}">＋ Tạo nghe–chép</button>`:""}</div></header><div class="hhj4-sentences">${sentences.map(([jp,vi,row],index)=>`<button data-hhj4-sentence="${index}" class="${index===instance.sentenceIndex?"active":""}"><b>${esc(jp)}</b><span>${esc(vi)}</span>${row?`<small>${row.translationLanguage.toUpperCase()} · ${row.author}</small>`:""}</button>`).join("")}</div><section class="hhj4-token-line">${tokens.map((token)=>token.row?`<button data-hhj4-reader-word="${token.row.id}" class="${s.knownWords[token.row.id]?"known":""}">${esc(token.text)}${s.furigana&&!s.knownWords[token.row.id]?`<small>${esc(token.row.kana)}</small>`:""}</button>`:esc(token.text)).join("")}</section><footer><button ${sourceSentence?`data-hhj5-save-sentence="${sourceSentence.id}"`:`data-hhj4-save-sentence="${esc(sentence[0])}"`}>＋ Lưu cả câu</button><span>Độ phủ: ${Math.round(known/Math.max(1,total)*100)}% · ${unknown.length<=1?"N+1 phù hợp":`${unknown.length} từ chưa biết`}</span></footer></article><aside class="hhj4-reader-detail">${selected?`<small>TỪ ĐANG CHỌN</small><h2>${esc(selected.word)}</h2><b>${esc(selected.kana)}</b><p>${esc(selected.meaning)}</p><span>${esc(selected.pos||"")} · ${esc(selected.conjugationType||"")}</span><button data-hhj4-speak="${esc(selected.word)}">▶ Nghe</button><button data-hhj4-save-word="${selected.id}">＋ SRS</button>`:`<div class="hhj4-empty"><b>${sourceSentence?`${sourceSentence.author} · ${sourceSentence.license}`:"Chạm một từ"}</b><p>${sourceSentence?`Bản dịch: ${sourceSentence.translationAuthor} · ${sourceSentence.translationLicense}`:"Chạm một từ để xem dạng từ điển."}</p></div>`}</aside></div></section>`;}

  function progressView(){const tool=instance.state.progressTool;return `<section class="hhj4-view"><header class="hhj4-section-head"><div><small>LEARNER & DATA CONTROL</small><h1>Tiến độ thật và dữ liệu có thể kiểm tra</h1><p>Không tạo điểm thi, chứng chỉ, bản dịch đã duyệt hoặc bảng xếp hạng giả.</p></div><button data-hhj4-export="json">Xuất dữ liệu</button></header><nav class="hhj4-subnav">${PROGRESS_TOOLS.map(([id,label])=>`<button data-hhj4-progress="${id}" class="${tool===id?"active":""}">${label}</button>`).join("")}</nav>${tool==="review"?reviewConsoleView():tool==="teacher"?teacherView():tool==="family"?familyView():tool==="data"?dataView():dualProgressView()}</section>`;}
  function dualProgressView(){const s=instance.state,done=Object.keys(s.missionProgress).length,reviewed=s.cards.reduce((sum,card)=>sum+(card.reviews||0),0);return `<div class="hhj4-dual-progress"><article><header><b>JLPT Knowledge Map</b><span>${s.jlptLevel}</span></header>${["Vocabulary","Grammar","Reading","Listening"].map((label,index)=>{const value=Math.min(100,Math.round(reviewed/12)+index*2);return`<label>${label}<progress max="100" value="${value}"></progress><b>${value}%</b></label>`;}).join("")}<p>Ước tính luyện tập nội bộ; không phải điểm JLPT chính thức.</p></article><article><header><b>JF/CEFR Can-do Map</b><span>${s.jfLevel}</span></header>${["Interaction","Speaking","Listening","Writing"].map((label,index)=>{const value=Math.min(100,Math.round(done/4)+index);return`<label>${label}<progress max="100" value="${value}"></progress><b>${value}%</b></label>`;}).join("")}<p>Dựa trên mission đã hoàn thành; speaking/writing giữ riêng.</p></article><section>${metric("Từ nhận biết",Object.keys(s.knownWords).length,"Đánh dấu đã biết")}${metric("Vốn chủ động",s.cards.filter(x=>x.reviews>=3).length,"Đã ôn ít nhất 3 lần")}${metric("SRS",s.cards.length,"5 loại thẻ")}${metric("Lỗi",s.mistakes.length,"Từ mọi bài học")}</section></div>`;}
  function teacherView(){const s=instance.state;return `<div class="hhj4-teacher"><form data-hhj4-class-form><small>TEACHER MODE</small><h2>Tạo lớp và giao bài</h2><label>Tên lớp<input name="name" required placeholder="Tiếng Nhật giao tiếp A1"></label><label>Bài giao<select name="assignment">${PATHS.map((row)=>`<option value="${row.id}">${row.title}</option>`).join("")}</select></label><label>Hạn hoàn thành<input type="date" name="due" required></label><label><input type="checkbox" name="lock"> Khóa đáp án trước hạn</label><button type="button" class="primary" data-hhj4-create-class>Tạo lớp</button></form><section><header><h3>${s.classrooms.length} lớp</h3><div><button data-hhj4-export="csv">Xuất CSV</button><button data-hhj4-print>In / PDF</button></div></header>${s.classrooms.map((row)=>`<article><b>${esc(row.name)}</b><span>${esc(row.assignment)} · hạn ${esc(row.due)}</span><small>${row.lock?"Đáp án đang khóa":"Cho phép xem đáp án"}</small></article>`).join("")||"<p>Chưa có lớp.</p>"}</section></div>`;}
  function familyView(){const f=instance.state.family,book=profiles();return `<div class="hhj4-teacher"><form class="hhj4-family" data-hhj4-family><header><small>FAMILY MODE</small><h2>An toàn cho hồ sơ trẻ em</h2><p>Không có tin nhắn riêng, quảng cáo cá nhân hóa hoặc bảng xếp hạng công khai.</p></header><label><input type="checkbox" name="enabled" ${f.enabled?"checked":""}> Bật quản lý phụ huynh</label><label>Giới hạn học mỗi ngày<input type="number" name="dailyLimit" min="5" max="120" value="${f.dailyLimit}"> phút</label><label><input type="checkbox" name="aiAllowed" ${f.aiAllowed?"checked":""}> Cho phép AI Tutor có hướng dẫn</label><label><input type="checkbox" name="publicRanking" disabled> Bảng xếp hạng công khai luôn tắt</label><button type="button" class="primary" data-hhj4-save-family>Lưu Family Mode</button></form><section><header><div><small>LEARNER PROFILES</small><h2>Hồ sơ tách riêng tiến độ</h2></div></header><label>Hồ sơ đang dùng<select data-hhj4-profile-select>${book.items.map((row)=>`<option value="${row.id}" ${row.id===book.active?"selected":""}>${esc(row.name)}</option>`).join("")}</select></label><form data-hhj4-profile-form><input name="name" maxlength="60" placeholder="Tên người học" required><select name="mode"><option value="little">Little Kids</option><option value="kids">Kids</option><option value="teen">Teens</option><option value="student">Students</option><option value="adult" selected>Adults</option><option value="senior">Senior</option></select><button type="button" data-hhj4-create-profile>Tạo hồ sơ</button></form><p>Dữ liệu được lưu theo <code>ownerId + learnerProfileId</code>; đổi hồ sơ không làm mất tiến độ hồ sơ khác.</p></section></div>`;}
  function reviewConsoleView(){const reviewed=reviewedVietnamese().filter((row)=>statusOf(row)[1]==="reviewed").length,sourceChecked=reviewedVietnamese().length-reviewed,missing=reviewedVietnamese().filter((row)=>!row.example&&!row.exampleVi).length,duplicates=sourcePack.words.length+(vietnamesePack?.words?.length||0)+(legacy.words?.length||0)-ALL_WORDS.length,candidates=reviewedVietnamese().filter((row)=>!instance.state.reviewOverrides[row.id]).slice(0,40),selected=effectiveWord(WORD_BY_ID.get(instance.reviewWordId)||candidates[0]),pending=instance.state.reviewQueue.filter((row)=>row.status==="pending");return `<div class="hhj5-review"><header><div><small>VIETNAMESE REVIEW CONSOLE</small><h2>Không nâng số “đã duyệt” bằng dịch máy</h2><p>Mỗi thay đổi giữ bản cũ, bản đề xuất, người duyệt, thời gian và trạng thái.</p></div><button data-hhj5-export-license>Xuất license manifest</button></header><div class="hhj4-metrics">${metric("Đã kiểm duyệt",reviewed.toLocaleString("vi-VN"),"Nội dung biên tập")}${metric("Đã kiểm tra nguồn",sourceChecked.toLocaleString("vi-VN"),"Cần biên tập tiếp")}${metric("Thiếu ví dụ cục bộ",missing.toLocaleString("vi-VN"),"Có thể bổ sung từ Sentence Bank")}${metric("Trùng đã loại",Math.max(0,duplicates).toLocaleString("vi-VN"),"Kanji + Kana")}</div><div class="hhj5-review-workspace"><aside class="hhj4-list"><header><b>Hàng đợi</b><span>${pending.length} đề xuất chờ</span></header>${candidates.map((row)=>`<button data-hhj5-review-select="${row.id}" class="${selected?.id===row.id?"active":""}"><span><strong>${esc(row.word)}</strong><small>${esc(row.meaning)}</small></span><i>${statusOf(row)[0]}</i></button>`).join("")}</aside>${selected?`<article><header><small>MỤC ĐANG DUYỆT</small><h2>${esc(selected.word)} · ${esc(selected.kana)}</h2></header><section class="hhj5-diff-grid"><div><small>HIỆN TẠI</small><p>${esc(WORD_BY_ID.get(selected.id)?.meaning||"")}</p><span>${esc(WORD_BY_ID.get(selected.id)?.exampleVi||"Chưa có ví dụ Việt")}</span></div><div><small>BẢN TRONG HỒ SƠ</small><p>${esc(selected.meaning)}</p><span>${esc(selected.exampleVi||"Chưa có ví dụ Việt")}</span></div></section><form data-hhj5-review-form data-word="${selected.id}"><label>Nghĩa Việt<input name="meaning" value="${esc(selected.meaningLanguage==="vi"?selected.meaning:"")}" required></label><label>Ví dụ Nhật<input name="example" value="${esc(selected.example||examplesForWord(selected.word,1)[0]?.text||"")}" required></label><label>Ví dụ Việt<input name="exampleVi" value="${esc(selected.exampleVi||examplesForWord(selected.word,1)[0]?.translation||"")}" required></label><label>Trợ từ<input name="particles" value="${esc((selected.particles||[]).join(", "))}" placeholder="に, で"></label><label>Collocation<input name="related" value="${esc((selected.related||[]).join(", "))}" placeholder="3–8 cụm"></label><button>Lưu đề xuất</button></form>${pending.filter((row)=>row.wordId===selected.id).map((row)=>`<section class="hhj5-proposal"><b>${esc(row.meaning)}</b><span>${esc(row.example)} · ${esc(row.exampleVi)}</span><div><button data-hhj5-review-reject="${row.id}">Từ chối</button><button class="primary" data-hhj5-review-approve="${row.id}">Duyệt vào hồ sơ</button></div></section>`).join("")}</article>`:"<article class='hhj4-empty'>Chọn mục để duyệt.</article>"}</div></div>`;}
  function dataView(){return `<div class="hhj4-data-source"><header><small>DATA QUALITY & LICENSE V5</small><h2>Dữ liệu đúng nguồn, đúng trạng thái và có rollback</h2></header><div>${metric("Từ độc nhất",ALL_WORDS.length.toLocaleString("vi-VN"),"Sau loại trùng Kanji + Kana")}${metric("Sentence Bank",SENTENCES.length.toLocaleString("vi-VN"),`${SENTENCES.filter(x=>x.translationLanguage==="vie").length.toLocaleString("vi-VN")} bản dịch Việt`)}${metric("KanjiVG",strokePack.count.toLocaleString("vi-VN"),"Stroke SVG thật")}${metric("Pack checksums",3,"JMdict · Tatoeba · KanjiVG")}</div><article><h3>JMdict / EDRDG</h3><p>30.000 mục nguồn mở bổ sung; nghĩa Anh tham chiếu. Không tự gán JLPT hoặc pitch.</p><code>${sourcePack.checksum}</code></article><article><h3>Tatoeba Sentence Bank</h3><p>Mỗi record giữ tác giả và giấy phép CC BY 2.0 FR hoặc CC0. Audio để trống nếu chưa xác minh license riêng.</p><code>${sentencePack.checksum}</code></article><article><h3>KanjiVG</h3><p>${strokePack.count.toLocaleString("vi-VN")} Kanji có path thứ tự nét theo CC BY-SA 3.0.</p><code>${strokePack.checksum}</code></article><section class="hhj5-pack-history"><h3>Lịch sử offline pack</h3>${instance.state.packHistory.slice().reverse().map((row)=>`<article><b>${esc(row.label)}</b><span>${row.at.slice(0,19).replace("T"," ")} · ${row.checksum}</span><button data-hhj5-pack-rollback="${row.versionKey}">Rollback snapshot</button></article>`).join("")||"<p>Chưa có snapshot. Tải một gói offline để tạo version đầu tiên.</p>"}</section></div>`;}

  function currentView(){switch(instance.state.activeTab){case"paths":return pathsView();case"practice":return practiceView();case"lookup":return lookupView();case"immersion":return immersionView();case"progress":return progressView();default:return todayView();}}
  function createClassFromForm(form){if(!form)return;const name=form.elements.namedItem("name")?.value.trim(),due=form.elements.namedItem("due")?.value;if(!name||!due){toast("Hãy nhập tên lớp và hạn hoàn thành.","warning");return;}instance.state.classrooms.push({id:`class-${Date.now()}`,name,assignment:form.elements.namedItem("assignment")?.value||"jf",due,lock:Boolean(form.elements.namedItem("lock")?.checked),createdAt:new Date().toISOString()});write();toast("Đã tạo lớp và lưu bài giao.");render();}
