    if(form.matches("[data-hhj5-lesson-production]")){const row=effectiveWord(WORD_BY_ID.get(form.dataset.word)),answer=String(form.elements.answer.value||"").trim(),correct=answer.includes(row.word)||answer.includes(row.kana);updateMastery(row.id,"production",correct);if(!correct)addMistake("production",`Tạo câu với ${row.word}`,`Câu phải dùng ${row.word} hoặc ${row.kana}`,answer,row.id);else{addCard("sentence",checksum(answer),{text:answer,prompt:`Câu tự tạo với ${row.word}`,correct:answer});instance.state.lesson.step=7;study(8);}toast(correct?"Đã lưu câu tự tạo vào SRS.":"Câu chưa chứa từ mục tiêu.",correct?"success":"warning");return render();}
    if(form.matches("[data-hhj5-active-form]")){const row=effectiveWord(WORD_BY_ID.get(form.dataset.word)),skill=form.dataset.skill,answer=String(form.elements.answer.value||"").trim(),correct=skill==="recall"?(normalizeJapanese(answer)===normalizeJapanese(row.word)||normalizeJapanese(answer)===normalizeJapanese(row.kana)):(answer.includes(row.word)||answer.includes(row.kana));updateMastery(row.id,skill,correct);if(!correct)addMistake(skill,skill==="recall"?row.meaning:`Tạo câu với ${row.word}`,skill==="recall"?`${row.word} / ${row.kana}`:`Câu chứa ${row.word}`,answer,row.id);else{study(6);if(skill==="production")addCard("sentence",checksum(answer),{text:answer,prompt:`Câu chủ động với ${row.word}`,correct:answer});}toast(correct?"Đã ghi nhận năng lực.":"Chưa đạt; mục này sẽ quay lại vòng ôn.",correct?"success":"warning");return render();}
    if(form.matches("[data-hhj5-review-form]")){const proposal={id:`review-${Date.now()}`,wordId:form.dataset.word,meaning:String(form.elements.meaning.value||"").trim(),example:String(form.elements.example.value||"").trim(),exampleVi:String(form.elements.exampleVi.value||"").trim(),particles:String(form.elements.particles.value||"").split(",").map(x=>x.trim()).filter(Boolean).slice(0,8),related:String(form.elements.related.value||"").split(",").map(x=>x.trim()).filter(Boolean).slice(0,8),status:"pending",createdAt:new Date().toISOString(),reviewer:ownerId()};instance.state.reviewQueue.push(proposal);write();toast("Đã lưu đề xuất; cần bấm Duyệt trước khi dùng trong hồ sơ.");return render();}
    if(form.matches("[data-hhj4-writing-form]")){const task=form.dataset.task,text=form.elements.text.value,result=writingFeedback(task,text);instance.writingResult=result;instance.state.writingHistory.unshift({task,...result,at:new Date().toISOString()});for(const issue of result.issues)addMistake(task,issue,result.suggestion,result.original,`${task}:${checksum(issue)}`);if(!result.issues.length)study(10);write();return render();}
