    if(event.target.matches("[data-hhj5-sentence-language]")){instance.sentenceLanguage=event.target.value;instance.sentenceId="";return render();}
    if(event.target.matches("[data-hhj4-profile-select]")){write();const book=profiles();book.active=event.target.value;localStorage.setItem(profilesKey(),JSON.stringify(book));instance.state=readState();return render();}
